head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf76110";
scwin.editor = undefined;
scwin.upload = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("contRegDdtm") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — jldstf76110: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.editor =new Dext5editor("dext5editor1"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf76110' }); }

try { scwin.upload =new Dext5Upload("dext5upload"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf76110' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf76110.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_reg_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_reg_onclick = async function(e){
    try {
        await scwin.reg()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf76110.btn_reg_onclick' }); }
};

/**
 * @method
 * @name btn_frame_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_frame_onclick = function(e){
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf76110.btn_frame_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name reg
 * @description reg 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reg = async function () {
    const sprtRoomtitle = $c.util.getComponent('ipt_sprtRoomtitle').getValue();
    if ($.trim(sprtRoomtitle).length === 0) {
        await $c.win.alert("제목을 입력해 주세요.");
        ($c.util.getComponent('ipt_sprtRoomtitle') && $c.util.getComponent('ipt_sprtRoomtitle').setFocus ? $c.util.getComponent('ipt_sprtRoomtitle').setFocus() : $c.util.getComponent('ipt_sprtRoomtitle').focus());
        return;
    }
    if (DEXT5.isEmpty("dext5editor1")) {
        await $c.win.alert("내용을 입력해 주세요.");
        DEXT5.setFocusToEditor("dext5editor1");
        return;
    }
    scwin.transfer();
};

/**
 * @method
 * @name transfer
 * @description transfer 처리
 * @returns {void}
 * @hidden N
 */
scwin.transfer = function () {
    DEXT5UPLOAD.Transfer("dext5upload");
};

/**
 * @method
 * @name DEXT5UPLOAD_OnTransfer_Complete
 * @description DEXT5 UPLOAD On Transfer Complete 처리
 * @param {String} dextId dextId
 * @returns {void}
 * @hidden N
 */
scwin.DEXT5UPLOAD_OnTransfer_Complete = function (dextId) {
    const textNew = DEXT5UPLOAD.GetNewUploadListForText("dext5upload");
    if (textNew != null) {
        const rtn = fn_newTextToString(textNew);
        $('#ipt_attachFileInfo', $('#regForm')).val(rtn);
    }
    $('#ipt_SCREN_ID', $('#regForm')).val("/jldstf76110/jldstf76110.xml");
    $('#ipt_method', $('#regForm')).val("regSprtRoom");
    const htmlText = DEXT5.getBodyValue("dext5editor1");
    $c.util.getComponent('ipt_sprtRoomContn').setValue(htmlText);
    const notHtmlText = DEXT5.getBodyTextValue("dext5editor1");
    $c.util.getComponent('ipt_sprtRoomContnNoHtml').setValue(notHtmlText);
    $('#regForm').submit();
};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function () {
    parent.fn_search();
};
